235	func runInvestigate(ctx context.Context, cmd *cobra.Command, args []string, f runFlags, deps Deps) error {
236		silentErr := deps.NewSilentError
237	
238		if _, err := paths.WorktreeRoot(ctx); err != nil {
239			cmd.SilenceUsage = true
240			fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Run `entire enable` first.")
