func realPromptYN(ctx context.Context, question string, def bool) (bool, error) {
    answer := def
    form := newAccessibleForm(huh.NewGroup(
        huh.NewConfirm().
            Title(question).
            Value(&answer),
    ))
    if err := form.RunWithContext(ctx); err != nil {
