```go
func (m investigateTUIModel) handleKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
    if msg.Code == 'c' && msg.Mod == tea.ModCtrl {
        m.cancelOnce.Do(m.cancel)
        return m, tea.Quit
    }
    if m.finished && !m.detailMode {
        return m, tea.Quit
    }

    if m.detailMode {
        return m.handleDetailKey(msg)
    }

    // Dashboard mode.
    if msg.Code == 'o' && msg.Mod == tea.ModCtrl {
        m.detailMode = true
        m.detailIdx = 0
        m.detailScroll = len(m.rows[0].buffer) - 1
        if m.detailScroll < 0 {
            m.detailScroll = 0
        }
        return m, tea.EnterAltScreen
    }
    return m, nil
}

func (m investigateTUIModel) handleDetailKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
    switch msg.Code {
    case tea.KeyEsc:
        m.detailMode = false
        return m, tea.ExitAltScreen
    case tea.KeyRight:
        m.detailIdx = (m.detailIdx + 1) % len(m.rows)
        m.detailScroll = max(len(m.rows[m.detailIdx].buffer)-1, 0)
    case tea.KeyLeft:
        m.detailIdx = (m.detailIdx - 1 + len(m.rows)) % len(m.rows)
        m.detailScroll = max(len(m.rows[m.detailIdx].buffer)-1, 0)
    case tea.KeyUp:
        if m.detailScroll > 0 {
            m.detailScroll--
        }
    case tea.KeyDown:
        if m.detailScroll < len(m.rows[m.detailIdx].buffer)-1 {
            m.detailScroll++
        }
    case tea.KeyPgUp:
        m.detailScroll = max(m.detailScroll-10, 0)
    case tea.KeyPgDown:
        m.detailScroll = min(m.detailScroll+10, len(m.rows[m.detailIdx].buffer)-1)
    case tea.KeyHome:
        m.detailScroll = 0
    case tea.KeyEnd:
        m.detailScroll = max(len(m.rows[m.detailIdx].buffer)-1, 0)
    }
    return m, nil
}
